CREATE COLUMN TABLE "TEST_AP"."OFRT" ("AbsId" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(100) NOT NULL , "DocType" NVARCHAR(1) DEFAULT 'B' NOT NULL , "FRTCounter" SMALLINT CS_INT, "MoveChk1" NVARCHAR(1) DEFAULT 'N', "MoveChk2" NVARCHAR(1) DEFAULT 'N', "MoveTo_1" SMALLINT CS_INT DEFAULT 0, "MoveTo_2" SMALLINT CS_INT DEFAULT 0, "Title_1" NVARCHAR(100), "Title_2" NVARCHAR(100), "ShowMiss" NVARCHAR(1) DEFAULT 'N', "ToTitle_1" SMALLINT CS_INT DEFAULT 0, "ToTitle_2" SMALLINT CS_INT DEFAULT 0, "UserSign" SMALLINT CS_INT, "DimCode" INTEGER CS_INT, PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OFRT_SECOND" ON "TEST_AP"."OFRT" ( "DocType" ASC, "Name" ASC )